   152	                    (!isInvoiceRoom || isArchivedRoom) &&
   153	                    (welcomeMessage?.messageHtml ? (
   154	                        <PressableWithoutFeedback
   155	                            onPress={() => {
   156	                                const activeRoute = Navigation.getReportRHPActiveRoute();
   157	                                if (ReportUtils.canEditReportDescription(report, policy)) {
   158	                                    Navigation.navigate(ROUTES.REPORT_DESCRIPTION.getRoute(report?.reportID ?? '-1', activeRoute));
   159	                                    return;
   160	                                }
   161	                                Navigation.navigate(ROUTES.REPORT_WITH_ID_DETAILS.getRoute(report?.reportID ?? '-1', activeRoute));
   162	                            }}
   163	                            style={styles.renderHTML}
   164	                            accessibilityLabel={translate('reportDescriptionPage.roomDescription')}
   165	                        >
   166	                            <RenderHTML html={welcomeMessage.messageHtml} />
   167	                        </PressableWithoutFeedback>
   168	                    ) : (
   169	                        <Text>
   170	                            <Text>{welcomeMessage.phrase1}</Text>
   171	                            {welcomeMessage.showReportName && (
   172	                                <Text
   173	                                    style={[styles.textStrong]}
   174	                                    onPress={navigateToReport}
   175	                                    suppressHighlighting
   176	                                >
   177	                                    {ReportUtils.getReportName(report)}
   178	                                </Text>
   179	                            )}
   180	                            {welcomeMessage.phrase2 !== undefined && <Text>{welcomeMessage.phrase2}</Text>}
   181	                        </Text>
   182	                    ))}
   183	                {isSelfDM && (
   184	                    <Text>
   185	                        <Text>{welcomeMessage.phrase1}</Text>
   186	                    </Text>
   187	                )}
   188	                {isSystemChat && (
   189	                    <Text>
   190	                        <Text>{welcomeMessage.phrase1}</Text>
   191	                    </Text>
   192	                )}
   193	                {isDefault && displayNamesWithTooltips.length > 0 && (
   194	                    <Text>
   195	                        <Text>{welcomeMessage.phrase1}</Text>
   196	                        {displayNamesWithTooltips.map(({displayName, accountID}, index) => (
   197	                            // eslint-disable-next-line react/no-array-index-key
   198	                            <Text key={`${displayName}${index}`}>
   199	                                <UserDetailsTooltip accountID={accountID}>
   200	                                    {ReportUtils.isOptimisticPersonalDetail(accountID) ? (
   201	                                        <Text style={[styles.textStrong]}>{displayName}</Text>
   202	                                    ) : (
   203	                                        <Text
   204	                                            style={[styles.textStrong]}
   205	                                            onPress={() => Navigation.navigate(ROUTES.PROFILE.getRoute(accountID, Navigation.getReportRHPActiveRoute()))}
   206	                                            suppressHighlighting
   207	                                        >
   208	                                            {displayName}
   209	                                        </Text>
   210	                                    )}
   211	                                </UserDetailsTooltip>
   212	                                {index === displayNamesWithTooltips.length - 1 && <Text>.</Text>}
   213	                                {index === displayNamesWithTooltips.length - 2 && <Text>{` ${translate('common.and')} `}</Text>}
   214	                                {index < displayNamesWithTooltips.length - 2 && <Text>, </Text>}
   215	                            </Text>
   216	                        ))}
   217	                    </Text>
   218	                )}
   219	                {shouldShowUsePlusButtonText && <Text>{translate('reportActionsView.usePlusButton', {additionalText})}</Text>}
   220	                {ReportUtils.isConciergeChatReport(report) && <Text>{translate('reportActionsView.askConcierge')}</Text>}
   221	            </View>
   222	        </>
   223	    );
   224	}
